  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Cliente {\n  id        String   @id @default(cuid())\n  nombre    String\n  email     String   @unique\n  password  String? // Opcional para usuarios de redes sociales\n  telefono  String?\n  activo    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Campos para autenticación social\n  googleId   String?       @unique\n  facebookId String?       @unique\n  proveedor  TipoProveedor @default(LOCAL)\n  avatar     String?\n\n  // Relaciones\n  suscripciones   Suscripcion[]\n  carritos        Carrito[]\n  pagos           Pago[]\n  credenciales    Credenciales[]\n  validacionesOCR ValidacionOCR[]\n\n  @@map(\"clientes\")\n}\n\nmodel Administrador {\n  id        String   @id @default(cuid())\n  nombre    String\n  email     String   @unique\n  password  String\n  activo    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  serviciosCreados Servicio[]\n\n  @@map(\"administradores\")\n}\n\nmodel Servicio {\n  id               String   @id @default(cuid())\n  nombre           String\n  descripcion      String\n  precio           Float\n  categoria        String\n  disponible       Boolean  @default(true)\n  logoUrl          String?  @map(\"logo_url\")\n  caracteristicas  Json?\n  credencialesBase Json? // Pool de credenciales configuradas por el admin\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  // Relaciones\n  administradorId String\n  administrador   Administrador @relation(fields: [administradorId], references: [id])\n\n  suscripciones Suscripcion[]\n  carritoItems  CarritoItem[]\n  credenciales  Credenciales[]\n\n  @@map(\"servicios\")\n}\n\nmodel Suscripcion {\n  id          String            @id @default(cuid())\n  estado      EstadoSuscripcion @default(ACTIVA)\n  fechaInicio DateTime          @default(now())\n  fechaFin    DateTime\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  // Relaciones\n  clienteId String\n  cliente   Cliente @relation(fields: [clienteId], references: [id])\n\n  servicioId String\n  servicio   Servicio @relation(fields: [servicioId], references: [id])\n\n  credenciales Credenciales[]\n  pagos        Pago[]\n\n  @@map(\"suscripciones\")\n}\n\nmodel Credenciales {\n  id        String   @id @default(cuid())\n  usuario   String\n  password  String\n  activas   Boolean  @default(true)\n  asignadas Boolean  @default(false) // Si están asignadas a un cliente\n  urlAcceso String? // URL del servicio\n  notas     String? // Notas adicionales del admin\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  clienteId String?\n  cliente   Cliente? @relation(fields: [clienteId], references: [id])\n\n  servicioId String\n  servicio   Servicio @relation(fields: [servicioId], references: [id])\n\n  suscripcionId String?\n  suscripcion   Suscripcion? @relation(fields: [suscripcionId], references: [id])\n\n  @@map(\"credenciales\")\n}\n\nmodel Carrito {\n  id        String   @id @default(cuid())\n  activo    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  clienteId String\n  cliente   Cliente @relation(fields: [clienteId], references: [id])\n\n  items CarritoItem[]\n  pagos Pago[]\n\n  @@map(\"carritos\")\n}\n\nmodel CarritoItem {\n  id        String   @id @default(cuid())\n  cantidad  Int      @default(1)\n  precio    Float\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  carritoId String\n  carrito   Carrito @relation(fields: [carritoId], references: [id], onDelete: Cascade)\n\n  servicioId String\n  servicio   Servicio @relation(fields: [servicioId], references: [id])\n\n  @@map(\"carrito_items\")\n}\n\nmodel MetodoPago {\n  id          String         @id @default(cuid())\n  nombre      String\n  tipo        TipoMetodoPago @unique\n  disponible  Boolean        @default(true)\n  descripcion String?\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n\n  // Relaciones\n  pagos Pago[]\n\n  @@map(\"metodos_pago\")\n}\n\nmodel Pago {\n  id              String     @id @default(cuid())\n  monto           Float\n  estado          EstadoPago @default(PENDIENTE)\n  referencia      String?    @unique\n  descripcion     String?\n  fechaValidacion DateTime? // Fecha cuando se validó el pago\n  validadoPor     String? // Método de validación: 'OCR', 'MANUAL', etc.\n  createdAt       DateTime   @default(now())\n  comprobanteUrl  String? // Ruta del comprobante subido\n  updatedAt       DateTime   @updatedAt\n\n  // Relaciones\n  clienteId String\n  cliente   Cliente @relation(fields: [clienteId], references: [id])\n\n  carritoId String?\n  carrito   Carrito? @relation(fields: [carritoId], references: [id])\n\n  suscripcionId String?\n  suscripcion   Suscripcion? @relation(fields: [suscripcionId], references: [id])\n\n  metodoPagoId String\n  metodoPago   MetodoPago @relation(fields: [metodoPagoId], references: [id])\n\n  qr              QR[]\n  validacionesOCR ValidacionOCR[]\n\n  @@map(\"pagos\")\n}\n\nmodel QR {\n  id        String   @id @default(cuid())\n  codigo    String   @unique\n  estado    EstadoQR @default(ACTIVO)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  pagoId String\n  pago   Pago   @relation(fields: [pagoId], references: [id])\n\n  @@map(\"qr_codes\")\n}\n\nmodel ValidacionOCR {\n  id             String @id @default(cuid())\n  imagenUrl      String\n  textoExtraido  String\n  datosExtraidos Json // Objeto JSON con monto, fecha, referencia, etc.\n  confianzaOCR   Float // Porcentaje de confianza del OCR (0-100)\n\n  // Datos extraídos del comprobante\n  montoDetectado       String?\n  fechaDetectada       String?\n  referenciaDetectada  String?\n  transaccionDetectada String?\n  bancoDetectado       String?\n\n  // Resultados de la validación\n  esValido                Boolean\n  coincidenciaMonto       Boolean @default(false)\n  coincidenciaFecha       Boolean @default(false)\n  coincidenciaReferencia  Boolean @default(false)\n  coincidenciaTransaccion Boolean @default(false)\n  porcentajeCoincidencia  Float // Porcentaje total de coincidencia (0-100)\n\n  // Auditoría\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  pagoId    String\n  pago      Pago    @relation(fields: [pagoId], references: [id])\n  usuarioId String\n  usuario   Cliente @relation(fields: [usuarioId], references: [id])\n\n  @@map(\"validaciones_ocr\")\n}\n\n// Enums\nenum EstadoSuscripcion {\n  ACTIVA\n  PAUSADA\n  CANCELADA\n  EXPIRADA\n}\n\nenum TipoMetodoPago {\n  TARJETA_CREDITO\n  TARJETA_DEBITO\n  TRANSFERENCIA\n  QR\n  EFECTIVO\n}\n\nenum EstadoPago {\n  PENDIENTE\n  COMPLETADO\n  FALLIDO\n  REEMBOLSADO\n}\n\nenum EstadoQR {\n  ACTIVO\n  USADO\n  EXPIRADO\n}\n\nenum TipoProveedor {\n  LOCAL\n  GOOGLE\n  FACEBOOK\n}\n",
